function openSchoolPlanModal(type=ui.planType){const meta=PLAN_TYPES[type];const body=`<form id="schoolPlanForm"><input type="hidden" name="type" value="${type}"><div class="form-grid"><div class="field wide"><label>البرنامج / المبادرة *</label><input name="title" required></div><div class="field wide"><label>الهدف *</label><textarea name="goal" required></textarea></div><div class="field"><label>الفئة المستهدفة</label><input name="targetGroup" placeholder="مثال: جميع الطلاب"></div><div class="field"><label>تاريخ التنفيذ</label><input type="date" name="date" value="${today()}"></div><div class="field"><label>المستهدف العددي</label><input type="number" name="targetCount" min="0"></div><div class="field"><label>المنفذ فعليًا</label><input type="number" name="actualCount" min="0"></div><div class="field"><label>قياس قبلي ٪</label><input type="number" min="0" max="100" name="pre"></div><div class="field"><label>قياس بعدي ٪</label><input type="number" min="0" max="100" name="post"></div><div class="field"><label>الحالة</label><select name="status"><option value="planned">مخطط</option><option value="inprogress">قيد التنفيذ</option><option value="done">مكتمل</option></select></div><div class="field"><label>المسؤول</label><input name="owner"></div><div class="field wide"><label>الشواهد / النتائج / الملاحظات</label><textarea name="notes" placeholder="ما الذي تم توثيقه؟ وما الأثر الظاهر؟"></textarea></div></div><div class="card-actions mt18"><button class="btn btn-primary">حفظ في خطة ${meta.label}</button></div></form>`;modal(`${meta.icon} برنامج جديد — ${meta.label}`,body,{onReady:w=>{$('#schoolPlanForm',w).onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);Store.state.schoolPlans.push(Object.fromEntries([...fd.entries(),['id',Store.uid('plan')],['createdAt',new Date().toISOString()]]));Store.save();w.remove();renderPlans();toast('تم حفظ البرنامج')}}})}
function editSchoolPlan(id){const x=Store.state.schoolPlans.find(p=>p.id===id);if(!x)return;const body=`<form id="editSchoolPlan"><div class="form-grid"><div class="field wide"><label>البرنامج</label><input name="title" value="${esc(x.title)}"></div><div class="field"><label>المنفذ فعليًا</label><input type="number" name="actualCount" value="${esc(x.actualCount||'')}"></div><div class="field"><label>قياس بعدي ٪</label><input type="number" name="post" value="${esc(x.post||'')}"></div><div class="field"><label>الحالة</label><select name="status"><option value="planned" ${x.status==='planned'?'selected':''}>مخطط</option><option value="inprogress" ${x.status==='inprogress'?'selected':''}>قيد التنفيذ</option><option value="done" ${x.status==='done'?'selected':''}>مكتمل</option></select></div><div class="field wide"><label>النتائج والشواهد</label><textarea name="notes">${esc(x.notes||'')}</textarea></div></div><div class="card-actions mt18"><button class="btn btn-primary">حفظ التحديث</button></div></form>`;modal('تحديث البرنامج وقياس الأثر',body,{onReady:w=>{$('#editSchoolPlan',w).onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);Object.assign(x,{title:fd.get('title'),actualCount:fd.get('actualCount'),post:fd.get('post'),status:fd.get('status'),notes:fd.get('notes')});Store.save();w.remove();renderPlans();toast('تم تحديث البرنامج')}}})}
function renderPlans(){
 const meta=PLAN_TYPES[ui.planType],list=Store.state.schoolPlans.filter(x=>x.type===ui.planType),done=list.filter(x=>x.status==='done').length,withImpact=list.filter(x=>x.post!==''&&x.post!=null&&x.pre!==''&&x.pre!=null),avgImpact=withImpact.length?withImpact.reduce((n,x)=>n+(num(x.post)-num(x.pre)),0)/withImpact.length:0,atRisk=list.filter(x=>SchoolBrain.schoolPlanItem(x).risk>=45).length;
 $('#page').innerHTML=hero('الخطط المدرسية','خطط مترابطة تقيس الأثر','التوجيه الطلابي والنشاط ورعاية الموهوبين؛ كل برنامج يحلل من حيث الوصول للفئة والأثر والزمن ثم يغذي عقل المنصة.',`<button class="btn btn-gold" id="addSchoolPlan">＋ برنامج جديد</button><button class="btn btn-secondary" data-go="intelligence">🧠 التحليل الشامل</button>`)+`<section class="section"><div class="container"><div class="tabs">${Object.entries(PLAN_TYPES).map(([id,m])=>`<button class="tab ${id===ui.planType?'active':''}" data-plan-type="${id}">${m.icon} ${m.label}</button>`).join('')}</div><div class="grid grid-4">${metric(`برامج ${meta.label}`,ar(list.length),'خلال العام','📚')}${metric('المكتمل',ar(done),list.length?pct(done/list.length*100):'—','✅')}${metric('متوسط الأثر',withImpact.length?`${avgImpact>=0?'+':''}${pct(avgImpact)}`:'—','قبل/بعد','📈')}${metric('تحتاج تدخلًا',ar(atRisk),'بحسب تحليل العقل','⚠️')}</div><div class="section-head mt18"><div><h2 class="section-title">${meta.icon} ${meta.label}</h2><p class="section-sub">الهدف → التنفيذ → الشاهد → النتيجة → قياس الأثر → قرار الاستمرار أو التعديل.</p></div></div>${list.length?`<div class="grid grid-3">${list.map(x=>{const a=SchoolBrain.schoolPlanItem(x),impact=a.delta,achieve=a.participationRatio;return `<div class="card"><div class="chips"><span class="status ${a.risk>=45?'late':a.risk>=25?'pending':''}">${esc(a.label)}</span><span class="chip">${fmtDate(x.date)}</span><span class="risk-pill ${a.risk>=60?'high':a.risk>=35?'medium':'low'}">مخاطر ${ar(Math.round(a.risk))}</span></div><h3 class="mt12">${esc(x.title)}</h3><p>${esc(x.goal)}</p><div class="grid grid-2 mt18"><div><small class="muted">الوصول للمستهدف العددي</small><div class="metric-value" style="font-size:22px">${achieve!==null?pct(achieve):'—'}</div></div><div><small class="muted">الأثر قبل/بعد</small><div class="metric-value" style="font-size:22px">${impact===null?'—':`${impact>=0?'+':''}${pct(impact)}`}</div></div></div>${a.reasons.length?`<div class="insight ${a.risk>=45?'warn':''}"><strong>تحليل العقل:</strong> ${esc(a.reasons.join(' '))}<br><strong>القرار:</strong> ${esc(a.action)}</div>`:''}${x.notes?`<div class="insight mt12">${esc(x.notes)}</div>`:''}<div class="card-actions"><button class="btn btn-small btn-secondary" data-edit-plan="${x.id}">تحديث</button><button class="btn btn-small btn-danger" data-del-plan="${x.id}">حذف</button></div></div>`}).join('')}</div>`:empty(`لا توجد برامج مسجلة في ${meta.label} بعد.`)}</div></section>`;$$('[data-plan-type]').forEach(b=>b.onclick=()=>{ui.planType=b.dataset.planType;renderPlans()});$('#addSchoolPlan').onclick=()=>openSchoolPlanModal(ui.planType);$$('[data-edit-plan]').forEach(b=>b.onclick=()=>editSchoolPlan(b.dataset.editPlan));$$('[data-del-plan]').forEach(b=>b.onclick=()=>{if(confirm('حذف البرنامج؟')){Store.state.schoolPlans=Store.state.schoolPlans.filter(x=>x.id!==b.dataset.delPlan);saveAndRender('تم الحذف')}});bindGo()
}
